    int rec[C + 1][1 << C], rec2[C + 1][1 << C];
    vector<int> order[C + 1], order2[C + 1];
    const int L = 45;
    vector<long long> dp(L + 1);
    vector<int> pi(L + 1);
    bool inited = false;
