void init() {
    const int C = solver::C;
    auto solve = [&](auto table, auto rec, auto order, int h) {
        for (int n = 0; n <= C; ++n) {
            fill_n(rec[n], 1 << n, -1);
            int pt = 0;
            auto dfs = [&](auto _dfs, int x, int d) -> void {
                assert(rec[n][x & ((1 << n) - 1)] == -1 || rec[n][x & ((1 << n) - 1)] == pt);
                rec[n][x & ((1 << n) - 1)] = pt;
                if (d == 0) return;
                for (int a = 0; a + 1 < n + h; ++a)
                    if ((x >> a & 3) == 1)
                        _dfs(_dfs, x ^ (3 << a), d - 1);
            };
            while (table[n][pt] != -1) {
                int x = table[n][pt];
                order[n].push_back(x); 
                dfs(dfs, x, 3);
                ++pt;
            }
        }
    };
    solve(solver::table, solver::rec, solver::order, 3);
    solve(solver::table2, solver::rec2, solver::order2, 0);
    auto &dp = solver::dp;
    auto &pi = solver::pi; 
    for (int i = 0; i <= solver::L; ++i) {
        if (i <= C) dp[i] = solver::order2[i].size(), pi[i] = i;
        for (int j = 0; j <= C && j < i; ++j) {
            long long v = (long long)solver::order[j].size() * dp[i - j];
            if (v > dp[i]) {
                dp[i] = v;
                pi[i] = j;
            }
        }
    }
}

string Alice(int x, int k) {
    using namespace solver;
    if (!inited) init(), inited = true;
    string res;

    auto pb = [&](int v, int len) {
        for (int i = 0; i < len; ++i)
            res += "IO"[v >> i & 1];
    };

    int len = 0;
    while (dp[len] <= x) x -= dp[len++];
    while (pi[len] != len) {
        int p = pi[len];
        assert(x / dp[len - p] < (long long)order[p].size());
        pb(order[p][x / dp[len - p]], p); 
        x %= dp[len - p];
        len -= p;
    }
    assert(x < (long long)order2[len].size());
    pb(order2[len][x], len);
    return res;
}

int Bob(string s, int k) {
    using namespace solver;
    if (!inited) init(), inited = true;

    auto take = [&](int v, int len) {
        for (int i = 0; i < len; ++i) {
            auto it = find(s.begin(), s.end(), "IO"[v >> i & 1]);
            assert(it != s.end());
            s.erase(it);
        }
    };

    int ans = 0;
    int len = s.size();
    for (int i = 0; i < len; ++i)
        ans += dp[i];
    while (pi[len] != len) {
        int p = pi[len];
        int x = 0;
        for (int i = p - 1; i >= 0; --i)
            x = x << 1 | int(s[i] == 'O');
        take(order[p][rec[p][x]], p);
        ans += rec[p][x] * dp[len - p];
        len -= p;
    }
    int x = 0;
    for (int i = len - 1; i >= 0; --i)
        x = x << 1 | int(s[i] == 'O');
    ans += rec2[len][x];
    return ans;
}